import Link from "next/link";
import { Suspense } from "react";
import { redirect } from "next/navigation";
import { requireWorkspace } from "@/lib/auth";
import { recurringCadences } from "@/lib/finance/cadences";
import { calendarDate } from "@/lib/finance/calendar";
import { expandSchedule } from "@/lib/finance/model";
import { formatMoney, monthlyEquivalent } from "./series";
import { DetectedPatterns } from "./detected";
import { OccurrenceReview } from "./occurrences";

type Schedule = { id: string; name: string; account_id: string | null; amount_minor: string; currency_code: string; cadence: string; starts_on: string; ends_on: string | null; schedule_anchor_on: string | null; source: string };
const UPCOMING_DAYS = 30;

export default async function RecurringPage() {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/login"); }
  const { supabase, workspace } = context;
  const money = (amount: string | bigint, currency: string) => formatMoney(amount, currency, workspace.locale);
  const today = calendarDate(new Date(), workspace.timezone);

  const [{ data: accounts, error: accountsError }, { data: scheduleData, error: schedulesError }] = await Promise.all([
    supabase.from("accounts").select("id, name").eq("workspace_id", workspace.id).order("name"),
    supabase.from("financial_assumptions").select("id, name, account_id, amount_minor::text, currency_code, cadence, starts_on, ends_on, schedule_anchor_on, source")
      .eq("workspace_id", workspace.id).eq("confirmed", true).eq("enabled", true).is("removed_at", null).in("cadence", recurringCadences).order("name").limit(500),
  ]);
  const names: Record<string, string> = Object.fromEntries((accounts ?? []).map(account => [account.id, account.name]));

  // Same expansion as the forecast, so "next" here matches Plan. Account-less schedules still get a date.
  const schedules = ((scheduleData ?? []) as Schedule[]).map(item => {
    const dated = { ...item, account_id: item.account_id ?? "unassigned" };
    const upcoming = expandSchedule(dated, today, UPCOMING_DAYS);
    const amount = BigInt(item.amount_minor);
    return { ...item, amount, next: expandSchedule(dated, today, 400)[0]?.date ?? null, upcoming: amount * BigInt(upcoming.length), monthly: monthlyEquivalent(amount, item.cadence) };
  }).sort((a, b) => (a.next ?? "9999").localeCompare(b.next ?? "9999") || a.name.localeCompare(b.name));
  const totals = new Map<string, { out: bigint; in: bigint; upcoming: bigint }>();
  for (const item of schedules) {
    if (!item.next) continue;
    const total = totals.get(item.currency_code) ?? { out: 0n, in: 0n, upcoming: 0n };
    if (item.monthly < 0n) total.out += item.monthly; else total.in += item.monthly;
    total.upcoming += item.upcoming;
    totals.set(item.currency_code, total);
  }

  return (
    <main className="mx-auto w-full max-w-[1400px] space-y-8 px-4 py-6 text-foreground sm:px-8 lg:py-8">
      <header className="space-y-4">
        <div className="flex flex-col gap-1">
          <p className="eyebrow">Money · bills, subscriptions, income</p>
          <h1 className="page-title">Recurring payments</h1>
          <p className="mt-1 text-sm text-muted-foreground">Confirmed bills, subscriptions and income. Suggestions below only reach your forecast once you confirm them.</p>
        </div>
      </header>
      {accountsError && <p role="alert">Could not load accounts: {accountsError.message}</p>}

      <section aria-label="Bills and subscriptions" className="space-y-3">
        <div className="flex flex-wrap items-end justify-between gap-4">
          <h2 className="text-sm font-medium">Bills and subscriptions</h2>
          {totals.size > 0 && <dl className="flex flex-wrap gap-x-6 gap-y-1 text-right text-sm">{[...totals].map(([currency, total]) => <div key={currency} className="grid">
            <dt className="text-xs text-muted-foreground">Per month ({currency})</dt>
            <dd className="font-mono font-semibold tabular-nums">{money(total.out, currency)}{total.in > 0n && <span className="ml-2 text-success">+{money(total.in, currency)} in</span>}</dd>
            <dd className="text-xs text-muted-foreground">Next {UPCOMING_DAYS} days: {money(total.upcoming, currency)}</dd>
          </div>)}</dl>}
        </div>
        {schedulesError ? <p role="alert">Could not load confirmed schedules: {schedulesError.message}</p> : schedules.length ? <div className="overflow-x-auto rounded-xl border border-border bg-card">
          <table className="w-full min-w-[480px] text-left text-sm">
            <thead className="border-b border-border text-xs text-muted-foreground"><tr>
              <th className="px-4 py-2.5 font-medium">Name</th><th className="px-3 py-2.5 font-medium">Cadence</th><th className="px-3 py-2.5 font-medium">Next</th>
              <th className="px-4 py-2.5 text-right font-medium">Amount</th>
            </tr></thead>
            <tbody className="divide-y divide-border">{schedules.map(item => <tr key={item.id} className={item.next ? "" : "text-muted-foreground"}>
              <td className="px-4 py-2.5"><Link href="/plan" className="font-medium hover:underline">{item.name}</Link><span className="ml-2 text-xs text-muted-foreground">{item.account_id ? names[item.account_id] ?? "Unknown account" : "No account"}</span></td>
              <td className="px-3 py-2.5 capitalize">{item.cadence}</td>
              <td className="whitespace-nowrap px-3 py-2.5 font-mono">{item.next ?? "Ended"}</td>
              <td className={`whitespace-nowrap px-4 py-2.5 text-right font-mono tabular-nums ${item.amount > 0n ? "text-success" : ""}`}>{money(item.amount, item.currency_code)}</td>
            </tr>)}</tbody>
          </table>
        </div> : <p className="rounded-xl border border-dashed border-border p-5 text-center text-sm text-muted-foreground">No confirmed schedules yet. Confirm a detected pattern below or add one in <Link href="/plan" className="underline">Plan</Link>.</p>}
        <p className="text-xs text-muted-foreground">Edit, pause or end a schedule in <Link href="/plan" className="underline">Plan</Link>. Monthly totals are per currency (52 weeks a year).</p>
      </section>

      <Suspense fallback={<p className="rounded-xl border border-border bg-card p-5 text-sm text-muted-foreground">Looking for recurring patterns in your history…</p>}>
        <DetectedPatterns supabase={supabase} workspace={workspace} names={names} />
      </Suspense>
      <Suspense fallback={null}>
        <OccurrenceReview supabase={supabase} workspace={workspace} accountNames={names} />
      </Suspense>
    </main>
  );
}
"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { reviewedLocalTimestamp } from "@/lib/finance/calendar";

import { recurringCadences } from "@/lib/finance/cadences";

const uuid = z.uuid();
const currency = z.string().regex(/^[A-Z]{3}$/);
// Compact expected versions keep 1000-source forms well below Next's default
// 1MB body limit. Owned full receipts are read and validated under RPC locks.
const receipt = z.object({id: uuid, version: z.number().int().min(0).max(2147483647)}).strict();
const receiptPayload = z.string().max(128000).refine(value => Buffer.byteLength(value,"utf8") <= 128000,"Evidence payload too large");

async function decideSeries(form: FormData, decision: "confirmed" | "dismissed") {
  const { supabase } = await requireWorkspace();
  const raw = receiptPayload.parse(form.get("sourceEvidence"));
  let parsed: unknown;
  try { parsed = JSON.parse(raw); } catch { throw new Error("Invalid source evidence"); }
  const evidence = z.array(receipt).min(3).max(1000).parse(parsed);
  const anchor = uuid.parse(form.get("runAnchorId"));
  if (new Set(evidence.map(row => row.id)).size !== evidence.length || !evidence.some(row => row.id === anchor)) throw new Error("Duplicate sources or missing anchor");
  const limited = z.enum(["true", "false"]).parse(form.get("evidenceLimited")) === "true";
  if (limited && evidence.length !== 1000) throw new Error("Invalid limited evidence");
  const { error } = await supabase.rpc("review_recurring_series_versions", {
    p_decision: decision,
    p_account_id: uuid.parse(form.get("accountId")),
    p_label: z.string().trim().min(1).max(200).parse(form.get("label")),
    p_cadence: z.enum(recurringCadences).parse(form.get("cadence")),
    p_currency_code: currency.parse(form.get("currencyCode")),
    p_evidence: evidence, p_run_anchor_id: anchor, p_evidence_limited: limited,
  });
  if (error) throw new Error(error.message);
  revalidatePath("/", "layout");
  redirect("/money/recurring");
}

export async function confirmSeries(form: FormData) { await decideSeries(form, "confirmed"); }
export async function declineSeries(form: FormData) { await decideSeries(form, "dismissed"); }

const versionedId = z.string().transform(value => {
  const [id, version] = value.split(":");
  return { id: uuid.parse(id), version: z.coerce.number().int().min(0).parse(version) };
});
export async function associateOccurrence(form: FormData) {
  const assumption = versionedId.parse(form.get("assumption"));
  const transaction = versionedId.parse(form.get("transaction"));
  const scheduledOn = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).parse(form.get("scheduledOn"));
  reviewedLocalTimestamp(`${scheduledOn}T00:00:00`, "UTC");
  const fulfillment = z.enum(["full", "partial"]).parse(form.get("fulfillment"));
  const { supabase } = await requireWorkspace();
  const { error } = await supabase.rpc("record_recurring_occurrence", {
    p_assumption_id: assumption.id, p_assumption_version: assumption.version, p_scheduled_on: scheduledOn,
    p_transaction_id: transaction.id, p_transaction_version: transaction.version, p_completes_occurrence: fulfillment === "full",
  });
  if (error) throw new Error(error.message);
  revalidatePath("/money/recurring"); revalidatePath("/plan"); revalidatePath("/");
}
export async function undoOccurrence(form: FormData) {
  const id = uuid.parse(form.get("settlementId"));
  const version = z.coerce.number().int().min(1).parse(form.get("version"));
  const { supabase } = await requireWorkspace();
  const { error } = await supabase.rpc("undo_recurring_occurrence", { p_settlement_id: id, p_version: version });
  if (error) throw new Error(error.message);
  revalidatePath("/money/recurring"); revalidatePath("/plan"); revalidatePath("/");
}

import Link from "next/link";
import type { SupabaseClient } from "@supabase/supabase-js";
import { detectRecurring, type RecurringSeries } from "@/lib/finance/recurring";
import { confirmSeries, declineSeries } from "./actions";
import { formatMoney as formatCurrency, seriesKey } from "./series";

const MAX_TRANSACTIONS = 10_000;
const PAGE_SIZE = 1000;

type TxRow = {
  id: string; posted_on: string; description: string; amount_minor: string; currency_code: string; account_id: string;
  merchant_id: string | null; version: number; status: "posted"; kind: "ordinary"; review_reasons: string[];
};
type Stored = { id: string; account_id: string; currency_code: string; cadence: string; status: string; label?: string; evidence_invalidated?: boolean; evidence_baseline?: unknown;
  recurring_series_transactions?: { transaction_id: string }[]; assumption?: { source: string; confirmed: boolean; enabled: boolean; removed_at: string | null } | { source: string; confirmed: boolean; enabled: boolean; removed_at: string | null }[] | null };

// Detection reads up to 10k postings in serial keyset pages, so the page streams this section.
export async function DetectedPatterns({ supabase, workspace, names }: { supabase: SupabaseClient; workspace: { id: string; locale: string }; names: Record<string, string> }) {
  const formatMoney = (amount: string | bigint, currency: string) => formatCurrency(amount, currency, workspace.locale);
  // Started now (builders are lazy thenables) so it runs while transactions page in.
  const storedQuery = Promise.resolve(supabase.from("recurring_series")
    .select("id, account_id, normalized_label, cadence, currency_code, status, assumption_id, label, evidence_invalidated, evidence_baseline, recurring_series_transactions(transaction_id), assumption:financial_assumptions(source,confirmed,enabled,removed_at)")
    .eq("workspace_id", workspace.id));

  const rows: TxRow[] = [];
  let queryError: string | null = null;
  // Keyset pages preserve chronological selection even when other rows are inserted.
  // They are not a transaction snapshot: decisions validate owned evidence versions again.
  let cursor: TxRow | undefined;
  while (rows.length <= MAX_TRANSACTIONS) {
    let query = supabase.from("transactions")
      .select("id, posted_on, description, amount_minor::text, currency_code, account_id, merchant_id, version, status, kind, review_reasons")
      .eq("workspace_id", workspace.id)
      .eq("status", "posted")
      .eq("kind", "ordinary").eq("review_reasons", "{}")
      .order("posted_on", { ascending: false }).order("id", { ascending: false });
    if (cursor) query = query.or(`posted_on.lt.${cursor.posted_on},and(posted_on.eq.${cursor.posted_on},id.lt.${cursor.id})`);
    const size = Math.min(PAGE_SIZE, MAX_TRANSACTIONS + 1 - rows.length);
    const { data, error } = await query.range(0, size - 1);
    if (error) { queryError = error.message; break; }
    const page = (data ?? []) as TxRow[];
    rows.push(...page);
    if (page.length < size) break;
    cursor = page.at(-1);
  }
  const { data: storedData, error: storedError } = await storedQuery;
  const stored = (storedData ?? []) as Stored[];
  const truncated = rows.length > MAX_TRANSACTIONS;
  const cutoff = truncated ? rows[MAX_TRANSACTIONS].posted_on : null;
  // Exclude the entire boundary date rather than presenting an arbitrary slice of that day's postings.
  if (cutoff) rows.splice(0, rows.length, ...rows.filter(row => row.posted_on > cutoff));
  const observedFrom = rows.at(-1)?.posted_on;
  const observedTo = rows[0]?.posted_on;

  let detected: RecurringSeries[] = [];
  let detectError: string | null = null;
  if (!queryError) {
    try {
      detected = detectRecurring(rows.map(row => ({ id: row.id, date: row.posted_on, description: row.description, amountMinor: BigInt(row.amount_minor),
        currencyCode: row.currency_code, accountId: row.account_id, merchantId: row.merchant_id })));
    } catch (error) {
      detectError = error instanceof Error ? error.message : String(error);
    }
  }
  const byId = new Map(rows.map(row => [row.id, row]));
  const candidates = detected.map(series => {
    const related = stored.filter(item => item.account_id === series.accountId && item.currency_code === series.currencyCode && item.cadence === series.cadence &&
      item.recurring_series_transactions?.some(link => series.transactionIds.includes(link.transaction_id)));
    const state = related.length === 1 ? related[0] : undefined;
    return { series, related, status: state?.status ?? "pending", assumption: Array.isArray(state?.assumption) ? state.assumption[0] : state?.assumption,
      evidence: series.transactionIds.map(id => byId.get(id)).filter((row): row is TxRow => Boolean(row)) };
  });
  const pending = candidates.filter(item => item.status === "pending"), reviewed = candidates.filter(item => item.status !== "pending");
  const invalidated = stored.filter(series => series.evidence_invalidated);

  const card = ({ series, related, status, assumption, evidence }: typeof candidates[number]) => {
    const hidden = <>
      <input type="hidden" name="accountId" value={series.accountId} />
      <input type="hidden" name="label" value={series.label} />
      <input type="hidden" name="cadence" value={series.cadence} />
      <input type="hidden" name="currencyCode" value={series.currencyCode} />
      <input type="hidden" name="sourceEvidence" value={JSON.stringify(evidence.map(row => ({ id: row.id, version: row.version })))} />
      <input type="hidden" name="runAnchorId" value={series.runAnchorId} />
      <input type="hidden" name="evidenceLimited" value={String(series.evidenceLimited)} />
    </>;
    const blocked = related.length > 1;
    return <article key={seriesKey(series)} className="rounded-xl border border-border bg-card px-4 py-3">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        <h3 className="min-w-0 flex-1 truncate text-sm font-semibold">{series.label}</h3>
        <span className="rounded bg-muted px-2 py-0.5 text-xs capitalize">{series.cadence}</span>
        {status === "confirmed" && <span className="rounded bg-success-soft px-2 py-0.5 text-xs text-success">Confirmed{assumption?.confirmed && assumption.enabled && !assumption.removed_at ? " · used in forecast" : " · review schedule in Plan"}</span>}
        {status === "dismissed" && <span className="rounded bg-muted px-2 py-0.5 text-xs text-muted-foreground">Dismissed</span>}
        <span className="font-mono text-sm tabular-nums">{formatMoney(series.amountMinMinor, series.currencyCode)}{series.amountMinMinor !== series.amountMaxMinor && <> to {formatMoney(series.amountMaxMinor, series.currencyCode)}</>}</span>
        <div className="flex gap-2">
          {status !== "confirmed" && <form action={confirmSeries}>{hidden}<button disabled={blocked} className="rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground hover:opacity-90 disabled:opacity-50">Confirm</button></form>}
          {status !== "dismissed" && <form action={declineSeries}>{hidden}<button disabled={blocked} className="rounded-lg border border-border px-3 py-1.5 text-sm font-medium hover:bg-muted disabled:opacity-50">Not recurring</button></form>}
        </div>
      </div>
      <p className="mt-1 text-xs text-muted-foreground">{names[series.accountId] ?? "Unknown account"} · {series.occurrences} observed payments (a count, not a probability)</p>
      {blocked && <p role="alert" className="mt-1 text-xs">Evidence overlaps several reviewed runs. Review their schedules in Plan before deciding.</p>}
      <details className="mt-1 text-xs">
        <summary className="cursor-pointer text-muted-foreground hover:text-foreground">Evidence ({evidence.length} posted transactions)</summary>
        {(series.evidenceLimited || series.sameDateAlternatives > 0) && <p className="mt-1 text-muted-foreground">{series.evidenceLimited && `Review evidence retains the original calendar anchor and the latest 999 of ${series.observedOccurrences} matching observations. `}{series.sameDateAlternatives > 0 && `${series.sameDateAlternatives} other similar same-date postings were not selected. They may represent separate purchases or obligations; review them before confirming.`}</p>}
        {assumption?.source === "user" && <p className="mt-1 text-muted-foreground">Your intentional Plan schedule is retained when confirming or declining this candidate. Edit or disable it in <Link href="/plan" className="underline">Plan</Link>.</p>}
        <ul className="mt-1 space-y-0.5 text-muted-foreground">{evidence.slice(0, 8).map(row => <li key={row.id}>
          <Link className="hover:underline" href={`/money/transactions?transaction=${row.id}`}>{row.posted_on} · {formatMoney(row.amount_minor, row.currency_code)} · {row.description}</Link></li>)}</ul>
        {evidence.length > 8 && <p className="mt-1 text-muted-foreground">…and {evidence.length - 8} more.</p>}
      </details>
    </article>;
  };

  return <>
    {invalidated.length > 0 && <section aria-label="Recurring source changes" className="rounded-xl border border-warning/40 p-5"><h2 className="text-sm font-medium">Confirmed source evidence changed</h2><p className="mt-2 text-sm">Inferred assumptions are disabled when their transaction evidence is reclassified. Intentional user assumptions are retained. Undo the source correction to restore unchanged inference, or review a new valid pattern before confirming it.</p><ul className="mt-3 space-y-3">{invalidated.map(series => <li key={series.id} className="text-sm"><p>{series.label} · {names[series.account_id] ?? "Account"}</p><div className="flex flex-wrap gap-3">{((series.evidence_baseline ?? []) as { id: string; posted_on: string }[]).map(source => <Link key={source.id} href={`/money/transactions?transaction=${source.id}`} className="underline">Source {source.posted_on}</Link>)}<Link href="/plan" className="underline">Review assumption in Plan</Link></div></li>)}</ul></section>}
    {storedError && <p role="alert">Could not load review state: {storedError.message}</p>}
    {queryError && <p role="alert">Could not load transactions: {queryError}</p>}
    {detectError && <p role="alert">Could not detect patterns: {detectError}</p>}

    <section aria-label="Detected patterns" className="space-y-3">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h2 className="text-sm font-medium">Suggestions {pending.length ? <span className="text-muted-foreground">({pending.length})</span> : null}</h2>
        <p className="text-xs text-muted-foreground">{observedFrom ? `Based on posted transactions from ${observedFrom} to ${observedTo}.` : "No posted transactions to analyze yet."}</p>
      </div>
      {truncated && <p className="text-xs text-muted-foreground">History limit reached. All postings on or before {cutoff} were excluded to retain complete posting dates. Older patterns may be absent.</p>}
      {!queryError && !detectError && !pending.length && <p className="rounded-xl border border-dashed border-border p-5 text-center text-sm text-muted-foreground">{detected.length ? "All detected patterns are reviewed." : "No recurring payments found yet. Import more history to improve detection."}</p>}
      {pending.map(card)}
      <details className="text-xs text-muted-foreground"><summary className="cursor-pointer hover:text-foreground">How detection works</summary><p className="mt-2">Looks at up to {MAX_TRANSACTIONS.toLocaleString(workspace.locale)} recent posted transactions. Statement intervals, missing statements and account completeness are unknown. Pending items, transfers and unresolved classifications are excluded. A pattern needs at least three payments, so yearly ones need two years of history. Confirming creates one forecast assumption; schedules you edited in Plan are kept. Regular purchases can look like this too, so check the evidence before confirming.</p></details>
    </section>

    {reviewed.length > 0 && <section aria-label="Reviewed patterns" className="space-y-3">
      <h2 className="text-sm font-medium">Reviewed <span className="text-muted-foreground">({reviewed.length})</span></h2>
      {reviewed.map(card)}
    </section>}
  </>;
}
import Link from "next/link";
import { recurringCadences } from "@/lib/finance/cadences";
import type { SupabaseClient } from "@supabase/supabase-js";
import { associateOccurrence, undoOccurrence } from "./actions";
import { formatMoney } from "./series";

export async function OccurrenceReview({ supabase, workspace, accountNames }: { supabase: SupabaseClient; workspace: { id: string; locale: string }; accountNames: Record<string, string> }) {
  const [assumptions, transactions, settlements] = await Promise.all([
    supabase.from("financial_assumptions").select("id, name, version, amount_minor::text, currency_code, starts_on").eq("workspace_id", workspace.id).eq("confirmed", true).eq("enabled", true).is("removed_at", null).in("cadence", recurringCadences).order("name").limit(500),
    supabase.from("transactions").select("id, account_id, description, version, posted_on, status, amount_minor::text, currency_code").eq("workspace_id", workspace.id).eq("kind", "ordinary").eq("review_reasons", "{}").in("status", ["pending", "posted"]).order("posted_on", { ascending: false }).limit(500),
    supabase.from("recurring_occurrence_settlements").select("id, assumption_id, transaction_id, scheduled_on, completes_occurrence, undone_at, version, receipt").eq("workspace_id", workspace.id).order("created_at", { ascending: false }).limit(500),
  ]);
  if (assumptions.error || transactions.error || settlements.error) return <section aria-label="Occurrence reconciliation" role="alert">Could not load occurrence associations. Reload to review settlements.</section>;
  // Nothing to match against until a schedule is confirmed.
  if (!assumptions.data?.length && !settlements.data?.length) return null;
  const names = new Map((assumptions.data ?? []).map(row => [row.id, row.name]));
  const inputClass = "min-h-10 rounded-lg border border-border bg-card px-3 py-2 text-sm";
  return <section aria-label="Occurrence reconciliation" className="space-y-3">
    <div>
      <h2 className="text-sm font-medium">Match a payment to a schedule</h2>
      <p className="mt-1 text-xs text-muted-foreground">Pick the transaction that paid a scheduled date. Nothing is matched automatically; undo a match before replacing it.</p>
    </div>
    <form action={associateOccurrence} className="grid gap-3 rounded-xl border border-border bg-card p-4 md:grid-cols-2">
      <label className="grid gap-1 text-sm">Confirmed assumption<select name="assumption" required className={inputClass} defaultValue=""><option value="" disabled>Select assumption</option>{(assumptions.data ?? []).map(row => <option key={row.id} value={`${row.id}:${row.version}`}>{row.name} · {formatMoney(row.amount_minor, row.currency_code, workspace.locale)} · starts {row.starts_on}</option>)}</select></label>
      <label className="grid gap-1 text-sm">Scheduled occurrence date<input name="scheduledOn" type="date" required className={inputClass} /></label>
