90	    current_value := to_jsonb(spending) || jsonb_build_object('limit_minor', spending.limit_minor::text);
91	    if not event_row.after ? 'rollover' then current_value:=current_value-array['rollover','rollover_from']; end if;
92	  end if;
93	  select * into event_row from public.planning_events where id = p_event_id for update;
