108	  if event_row.entity_type = 'assumption' then
109	    if event_row.before is null then
110	      update public.financial_assumptions set enabled = false, removed_at = now(), source = 'user', confirmed = true where id = event_row.entity_id;
111	    else
112	      assumption := jsonb_populate_record(null::public.financial_assumptions, event_row.before);
