"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { reviewedLocalTimestamp } from "@/lib/finance/calendar";
import { recurringCadences } from "@/lib/finance/cadences";
import { parseManualAmount } from "@/app/money/transactions/input";
import { createSchedule, decideSeries, editSchedule, removeSchedule, scheduleFields, type ScheduleFields } from "./schedules";

/** What a recurring form shows after submitting: an error to fix, or done. Failures never reach the error page. */
export type ActionState = { error?: string; done?: number };

const uuid = z.uuid();
const currency = z.string().regex(/^[A-Z]{3}$/);
// Compact expected versions keep 1000-source forms well below Next's default
// 1MB body limit. Owned full receipts are read and validated under RPC locks.
const receipt = z.object({id: uuid, version: z.number().int().min(0).max(2147483647)}).strict();
const receiptPayload = z.string().max(128000).refine(value => Buffer.byteLength(value,"utf8") <= 128000,"Evidence payload too large");

async function run(work: () => Promise<unknown>): Promise<ActionState> {
  try { await work(); }
  catch (cause) {
    if (cause instanceof z.ZodError) return { error: cause.issues[0]?.message ?? "Check the form" };
    return { error: cause instanceof Error ? cause.message : String(cause) };
  }
  revalidatePath("/", "layout");
  return { done: Date.now() };
}

function seriesFrom(form: FormData) {
  const raw = receiptPayload.parse(form.get("sourceEvidence"));
  let parsed: unknown;
  try { parsed = JSON.parse(raw); } catch { throw new Error("Invalid source evidence"); }
  const evidence = z.array(receipt).min(3).max(1000).parse(parsed);
  const anchor = uuid.parse(form.get("runAnchorId"));
  if (new Set(evidence.map(row => row.id)).size !== evidence.length || !evidence.some(row => row.id === anchor)) throw new Error("Duplicate sources or missing anchor");
  const evidenceLimited = z.enum(["true", "false"]).parse(form.get("evidenceLimited")) === "true";
  if (evidenceLimited && evidence.length !== 1000) throw new Error("Invalid limited evidence");
  return { accountId: uuid.parse(form.get("accountId")), label: z.string().trim().min(1).max(200).parse(form.get("label")), cadence: z.enum(recurringCadences).parse(form.get("cadence")),
    currencyCode: currency.parse(form.get("currencyCode")), evidence, runAnchorId: anchor, evidenceLimited };
}

/** The editable fields of the dialog: a positive amount plus a direction, so "coming in" never needs a minus sign. */
function fieldsFrom(form: FormData, currencyCode: string): ScheduleFields {
  const amount = parseManualAmount(String(form.get("amount") ?? ""), currencyCode);
  if (amount <= 0n) throw new Error("Enter an amount above zero");
  const direction = z.enum(["out", "in"]).parse(form.get("direction"));
  return scheduleFields.parse({ name: form.get("name"), amountMinor: (direction === "out" ? -amount : amount).toString(), cadence: form.get("scheduleCadence") ?? form.get("cadence"),
    startsOn: form.get("startsOn"), category: String(form.get("category") ?? "").trim() || null });
}

export async function confirmSeries(_: ActionState, form: FormData) {
  return run(async () => {
    const series = seriesFrom(form);
    await decideSeries(await requireWorkspace(), series, "confirmed", form.has("amount") ? fieldsFrom(form, series.currencyCode) : {});
  });
}
export async function declineSeries(_: ActionState, form: FormData) {
  return run(async () => { await decideSeries(await requireWorkspace(), seriesFrom(form), "dismissed"); });
}

export async function addSchedule(_: ActionState, form: FormData) {
  return run(async () => {
    const context = await requireWorkspace();
    const accountId = uuid.parse(form.get("accountId"));
    const { data: account } = await context.supabase.from("accounts").select("currency_code").eq("workspace_id", context.workspace.id).eq("id", accountId).maybeSingle();
    if (!account) throw new Error("Account not found");
    await createSchedule(context, accountId, fieldsFrom(form, account.currency_code));
  });
}
export async function updateSchedule(_: ActionState, form: FormData) {
  return run(async () => {
    await editSchedule(await requireWorkspace(), uuid.parse(form.get("assumptionId")), fieldsFrom(form, currency.parse(form.get("currencyCode"))), crypto.randomUUID());
  });
}
export async function deleteSchedule(_: ActionState, form: FormData) {
  return run(async () => { await removeSchedule(await requireWorkspace(), uuid.parse(form.get("assumptionId")), crypto.randomUUID()); });
}

const versionedId = z.string().transform(value => {
  const [id, version] = value.split(":");
  return { id: uuid.parse(id), version: z.coerce.number().int().min(0).parse(version) };
});
export async function associateOccurrence(_: ActionState, form: FormData) {
  return run(async () => {
    const assumption = versionedId.parse(form.get("assumption"));
    const transaction = versionedId.parse(form.get("transaction"));
    const scheduledOn = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).parse(form.get("scheduledOn"));
    reviewedLocalTimestamp(`${scheduledOn}T00:00:00`, "UTC");
    const fulfillment = z.enum(["full", "partial"]).parse(form.get("fulfillment"));
    const { supabase } = await requireWorkspace();
    const { error } = await supabase.rpc("record_recurring_occurrence", {
      p_assumption_id: assumption.id, p_assumption_version: assumption.version, p_scheduled_on: scheduledOn,
      p_transaction_id: transaction.id, p_transaction_version: transaction.version, p_completes_occurrence: fulfillment === "full",
    });
    if (error) throw new Error(error.message);
  });
}
export async function undoOccurrence(_: ActionState, form: FormData) {
  return run(async () => {
    const id = uuid.parse(form.get("settlementId"));
    const version = z.coerce.number().int().min(1).parse(form.get("version"));
    const { supabase } = await requireWorkspace();
    const { error } = await supabase.rpc("undo_recurring_occurrence", { p_settlement_id: id, p_version: version });
    if (error) throw new Error(error.message);
  });
}

"use client";

import { useActionState, useEffect, useState } from "react";
import { Modal } from "@/components/command-palette";
import { recurringCadences } from "@/lib/finance/cadences";
import type { ActionState } from "./actions";

type Action = (state: ActionState, form: FormData) => Promise<ActionState>;
const inputClass = "min-h-10 w-full rounded-lg border border-border bg-background px-3 py-2 text-sm";
const cadenceWords: Record<string, string> = { weekly: "Every week", biweekly: "Every two weeks", monthly: "Every month", quarterly: "Every quarter", yearly: "Every year" };

function Hidden({ values }: { values: Record<string, string> }) {
  return <>{Object.entries(values).map(([name, value]) => <input key={name} type="hidden" name={name} value={value} />)}</>;
}

/** A plain form whose failure is shown next to it instead of crashing the page. */
export function ActionForm({ action, hidden = {}, className, children }: { action: Action; hidden?: Record<string, string>; className?: string; children: React.ReactNode }) {
  const [state, submit, pending] = useActionState(action, {});
  return <form action={submit} className={className}>
    <Hidden values={hidden} />
    <fieldset disabled={pending} className="contents">{children}</fieldset>
    {state.error && <p role="alert" className="basis-full text-xs text-danger">{state.error}</p>}
  </form>;
}

export type ScheduleDefaults = { name: string; amount: string; direction: "out" | "in"; cadence: string; startsOn: string; category: string; currencyCode?: string };

/** Opens a dialog to confirm, edit or add a recurring payment: how much, which way, how often, the next date and a category. */
export function ScheduleDialog({ title, trigger, triggerClassName, action, remove, hidden = {}, defaults, accounts, categories, submitLabel }: {
  title: string; trigger: React.ReactNode; triggerClassName?: string; action: Action; remove?: Action; hidden?: Record<string, string>; defaults: ScheduleDefaults;
  accounts?: { id: string; name: string; currencyCode: string }[]; categories: string[]; submitLabel: string;
}) {
  const [open, setOpen] = useState(false);
  const [state, submit, pending] = useActionState(action, {});
  const [removed, removeSubmit, removing] = useActionState(remove ?? (async () => ({})), {});
  const [values, setValues] = useState(defaults);
  const [accountId, setAccountId] = useState(accounts?.[0]?.id ?? "");
  // Close once a submission succeeds; the page itself is refreshed by the action.
  useEffect(() => { if (state.done || removed.done) setOpen(false); }, [state.done, removed.done]);
  const currencyCode = accounts ? accounts.find(account => account.id === accountId)?.currencyCode ?? "" : defaults.currencyCode ?? "";
  const set = (key: keyof ScheduleDefaults) => (event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setValues(current => ({ ...current, [key]: event.target.value }));
  const summary = values.amount && values.startsOn ? `${cadenceWords[values.cadence] ?? ""}: ${values.amount} ${currencyCode} ${values.direction === "out" ? "going out" : "coming in"}, next on ${values.startsOn}` : "";
  const listId = `categories-${title.replace(/\W/g, "")}`;
  return <>
    <button type="button" className={triggerClassName} onClick={() => { setValues(defaults); setOpen(true); }}>{trigger}</button>
    <Modal open={open} onClose={() => setOpen(false)} label={title} className="inset-0 size-full items-center justify-center px-4">
      <form action={submit} className="grid w-full max-w-md gap-3 rounded-xl border border-border bg-card p-5 shadow-xl">
        <Hidden values={{ ...hidden, ...(currencyCode ? { currencyCode } : {}) }} />
        <h2 className="text-base font-semibold">{title}</h2>
        {summary && <p className="rounded-lg bg-muted px-3 py-2 text-sm">{summary}</p>}
        <label className="grid gap-1 text-sm">Name<input name="name" required maxLength={120} value={values.name} onChange={set("name")} className={inputClass} /></label>
        {accounts && <label className="grid gap-1 text-sm">Account<select name="accountId" required value={accountId} onChange={event => setAccountId(event.target.value)} className={inputClass}>
          {accounts.map(account => <option key={account.id} value={account.id}>{account.name} ({account.currencyCode})</option>)}</select></label>}
        <div className="grid grid-cols-2 gap-3">
          <label className="grid gap-1 text-sm">Direction<select name="direction" value={values.direction} onChange={set("direction")} className={inputClass}>
            <option value="out">Going out</option><option value="in">Coming in</option></select></label>
          <label className="grid gap-1 text-sm">Amount{currencyCode && ` (${currencyCode})`}<input name="amount" required inputMode="decimal" pattern="\d+(\.\d+)?" value={values.amount} onChange={set("amount")} className={inputClass} /></label>
          <label className="grid gap-1 text-sm">How often<select name="scheduleCadence" value={values.cadence} onChange={set("cadence")} className={inputClass}>
            {recurringCadences.map(cadence => <option key={cadence} value={cadence}>{cadenceWords[cadence]}</option>)}</select></label>
          <label className="grid gap-1 text-sm">Next date<input name="startsOn" type="date" required value={values.startsOn} onChange={set("startsOn")} className={inputClass} /></label>
        </div>
        <label className="grid gap-1 text-sm">Category<input name="category" list={listId} maxLength={100} placeholder="e.g. Job, Rent, Subscriptions" value={values.category} onChange={set("category")} className={inputClass} /></label>
        <datalist id={listId}>{categories.map(name => <option key={name} value={name} />)}</datalist>
        {(state.error || removed.error) && <p role="alert" className="text-sm text-danger">{state.error ?? removed.error}</p>}
        <div className="flex flex-wrap items-center gap-2">
          <button disabled={pending || removing} className="min-h-10 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground disabled:opacity-50">{pending ? "Saving…" : submitLabel}</button>
          <button type="button" onClick={() => setOpen(false)} className="min-h-10 rounded-lg border border-border px-4 text-sm hover:bg-muted">Cancel</button>
          {remove && <button formAction={removeSubmit} formNoValidate disabled={pending || removing} className="ml-auto min-h-10 rounded-lg px-3 text-sm text-danger hover:bg-muted disabled:opacity-50">{removing ? "Removing…" : "Remove from recurring"}</button>}
        </div>
      </form>
    </Modal>
  </>;
}

