/** What detection caught since you last looked: price changes on confirmed payments and new patterns. Shown on Overview and Recurring. */
export async function RecurringReview({ supabase, workspace, showNew = true }: { supabase: SupabaseClient; workspace: { id: string; locale: string }; showNew?: boolean }) {
  const suggestions = await loadSuggestions(supabase, workspace).catch(() => null);
  if (!suggestions) return null;
  const changes = priceChanges(suggestions.candidates);
  const fresh = showNew ? suggestions.pending.filter(item => item.related.length <= 1).length : 0;
  if (!changes.length && !fresh) return null;
  const money = (minor: string, currency: string) => formatMoney(minor, currency, workspace.locale);
  return <section aria-label="Recurring to review" className="space-y-2 rounded-xl border border-ai-border bg-ai-soft p-4">
    <h2 className="text-sm font-medium text-ai">Recurring to review</h2>
    {changes.map(({ series, evidence, schedule, latest }) => {
      const decision = seriesDecision({ series, evidence });
      const abs = (minor: string) => formatInputAmount(minor.replace("-", ""), series.currencyCode);
      // Re-confirming links the new charge, so the same change is not asked about twice; the amount is the one chosen.
      const hidden = (amount: string) => ({ accountId: decision.accountId, label: decision.label, cadence: decision.cadence, currencyCode: decision.currencyCode,
        sourceEvidence: JSON.stringify(decision.evidence), runAnchorId: decision.runAnchorId, evidenceLimited: String(decision.evidenceLimited),
        name: schedule.name, amount: abs(amount), direction: amount.startsWith("-") ? "out" : "in", scheduleCadence: schedule.cadence,
        startsOn: schedule.starts_on, shownStartsOn: schedule.starts_on, category: schedule.category?.name ?? "" });
      const up = BigInt(latest.amount_minor.replace("-", "")) > BigInt(schedule.amount_minor.replace("-", ""));
      return <article key={series.runAnchorId} className="flex flex-wrap items-center gap-x-3 gap-y-2 text-sm">
        <p className="min-w-0 flex-1"><span className="font-medium">{schedule.name}</span> {up ? "went up" : "went down"}: scheduled {money(schedule.amount_minor, series.currencyCode)}, charged {money(latest.amount_minor, series.currencyCode)} on {latest.posted_on}.</p>
        <ActionForm action={confirmSeries} hidden={hidden(latest.amount_minor)} className="flex flex-col gap-1"><button className="rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground">Update to {money(latest.amount_minor, series.currencyCode)}</button></ActionForm>
        <ActionForm action={confirmSeries} hidden={hidden(schedule.amount_minor)} className="flex flex-col gap-1"><button className="rounded-lg border border-border px-3 py-1.5 text-sm hover:bg-muted">Keep {money(schedule.amount_minor, series.currencyCode)}</button></ActionForm>
      </article>;
    })}
    {fresh > 0 && <p className="text-sm">{fresh === 1 ? "1 new recurring payment was" : `${fresh} new recurring payments were`} found in your transactions. <Link href="/money/recurring" className="underline">Review and confirm</Link></p>}
  </section>;
}
